//! Direct contracts for per-blit and font helpers. Generated blocks remain an
//! additional independent state transcript; only private snapshots are mutated.
use crate::native_batch_kernel::{Machine,Outcome,fp_div,fp_mul};
fn word(b:&[u8],o:usize)->u32{u32::from_le_bytes(b[o..o+4].try_into().unwrap())}
fn put(b:&mut[u8],o:usize,v:u32){b[o..o+4].copy_from_slice(&v.to_le_bytes());}
fn nz(v:u32)->u32{(v&0x80000000)|if v==0{0x40000000}else{0}}
pub(crate)fn calculate(mut m:Machine,r:usize)->Option<Outcome>{match r{
 0=>{let c=m.c;let image=&m.regions[1].bytes;let x=c.regs[1].wrapping_add(word(image,36));let y=c.regs[2].wrapping_add(word(image,40));let dx=word(image,60);let dy=word(image,64);let offset_y=word(image,40);let sx=word(image,28);let sy=word(image,32);let vx=fp_mul(fp_div((x as i32 as f32).to_bits(),(dx as i32 as f32).to_bits())?,sx)?;let vy=fp_mul(fp_div((y as i32 as f32).to_bits(),(dy as i32 as f32).to_bits())?,sy)?;let out_y=word(&m.regions[0].bytes,20);for(o,v)in[(0,out_y),(4,c.regs[3]),(8,c.regs[2]),(12,c.regs[1]),(16,c.regs[0])]{put(&mut m.regions[0].bytes,o,v);}put(&mut m.regions[2].bytes,0,vx);put(&mut m.regions[3].bytes,0,vy);m.c.regs[0]=out_y;m.c.regs[1]=dy;m.c.regs[2]=offset_y;m.c.regs[9]=out_y;m.c.extregs[0]=vy;m.c.extregs[4]=sy;}
 1|2=>{let c=m.c;let(a,red,green,blue)=if r==1{let x=c.regs[0];(if x>>24==0{255}else{x>>24},x>>16&255,x>>8&255,x&255)}else{let p=&m.regions[1].bytes;(word(p,12),word(p,0),word(p,4),word(p,8))};let div=|x:u32|if r==1{x.wrapping_mul(a)/255}else{(x.wrapping_mul(a)as i32).wrapping_div(255)as u32};let(b,g,re)=(div(blue),div(green),div(red));let alpha=a<<24;let ab=alpha|(b<<16);let agb=ab|(g<<8);let result=agb|re;let frame=&mut m.regions[0].bytes;if r==1{for(o,v)in[(0,agb),(4,ab),(8,alpha),(12,255),(16,a),(20,blue),(24,green),(28,red),(32,c.regs[0]),(36,c.regs[7]),(40,c.regs[14])]{put(frame,o,v);}m.c.cpsr=(c.cpsr&0x0fffffff)|nz(result);}else{for(o,v)in[(0,agb),(4,ab),(8,255),(12,alpha),(16,c.regs[0]),(20,c.regs[7]),(24,c.regs[14])]{put(frame,o,v);}m.c.cpsr=(c.cpsr&0x1fffffff)|nz(result)|((g>>24&1)<<29);}m.c.regs[0]=result;m.c.regs[1]=agb;m.c.regs[2]=a;m.c.regs[3]=a;}
 3=>{let c=m.c;let flag=m.regions[1].bytes[49]as u32;for(o,v)in[(4,c.regs[0]),(8,c.regs[0]),(12,c.regs[7]),(16,c.regs[14])]{put(&mut m.regions[0].bytes,o,v);}m.c.regs[1]=flag;m.c.cpsr&=0x3fffffff;}
 4..=6=>{let c=m.c;let(a,b)=if r==4{(word(&m.regions[1].bytes,0),word(&m.regions[2].bytes,0))}else{(word(&m.regions[1].bytes,0)&65535,word(&m.regions[2].bytes,0)&65535)};put(&mut m.regions[0].bytes,0,c.regs[1]);put(&mut m.regions[0].bytes,4,c.regs[0]);m.cmp(a,b);m.c.regs[0]=u32::from(a<b);m.c.regs[1]=b;}
 14=>{let c=m.c;let left=c.regs[0];let right=c.regs[1];let la=m.read(left,4)?;let ra=m.read(right,4)?;let lb=m.read(left+4,4)?;let rb=m.read(right+4,4)?;let(a,b)=if la!=ra{(m.read(la+88,4)?,m.read(ra+88,4)?)}else{let a=m.read(lb+16,4)?;let b=m.read(rb+16,4)?;if a!=b{(a,b)}else{(m.read(lb+88,4)?,m.read(rb+88,4)?)}};let result=u32::from((a as i32)<(b as i32));for(o,v)in[(0,left),(4,right),(8,left)]{put(&mut m.regions[0].bytes,o,v);}m.regions[0].bytes[12]=result as u8;m.cmp(a,b);m.c.regs[0]=result;m.c.regs[1]=result;m.c.regs[2]=b;}
 _=>return crate::native_batch_generated::calculate(m,r)
}Some(m.finish())}
